<template><div v-loading="loading"><div class="page-header"><div><h1>商户工作台</h1><p>{{ data?.communityName || '当前社区' }} 的实时运营概况</p></div><ElTag v-if="data" type="success" effect="light">运行中</ElTag></div><div class="metrics"><ElCard v-for="item in metrics" :key="item.label" shadow="never" class="panel-card"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.hint }}</small></ElCard></div><ElCard class="panel-card" shadow="never"><template #header><strong>社区信息</strong></template><ElDescriptions v-if="data" :column="2" border><ElDescriptionsItem label="社区名称">{{ data.communityName }}</ElDescriptionsItem><ElDescriptionsItem label="社区编码">{{ data.communityCode }}</ElDescriptionsItem><ElDescriptionsItem label="社区 ID">{{ data.communityId }}</ElDescriptionsItem><ElDescriptionsItem label="部署模式">开源单社区</ElDescriptionsItem></ElDescriptions></ElCard></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{getDashboard,type Dashboard}from'@/api/merchant';const loading=ref(false),data=ref<Dashboard>();const metrics=computed(()=>[{label:'社区成员',value:data.value?.memberCount??0,hint:'当前社区成员'},{label:'运营圈子',value:data.value?.circleCount??0,hint:'已创建圈子'},{label:'内容总量',value:data.value?.postCount??0,hint:'社区帖子'},{label:'待审核',value:data.value?.pendingReviewCount??0,hint:'待处理内容'}]);onMounted(async()=>{loading.value=true;try{data.value=await getDashboard()}catch{ElMessage.error('商户概览加载失败')}finally{loading.value=false}})</script>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:20px}.metrics span,.metrics small{display:block;color:#8791a7;font-size:13px}.metrics strong{display:block;margin:12px 0 8px;font-size:32px}</style>
